// Version of "Faster closest point (2 pass)" https://www.shadertoy.com/view/XcVBzh
// The main difference is that a fixed sample rate of 64 is used with a target of 4096 and uses 4 buffers rather than multiple frames

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    ivec2 coord = ivec2(floor(fragCoord));

    // show the acculated distance map as it is being created (flash warning)
    vec4 last_value = texelFetch(iChannel0, coord, 0);

    // show the closest pixel from the coord in all directions for now
    ivec2 last_top_right = unpack_2d_pos(last_value.r);
    ivec2 last_bottom_right = unpack_2d_pos(last_value.g);
    ivec2 last_bottom_left = unpack_2d_pos(last_value.b);
    ivec2 last_top_left = unpack_2d_pos(last_value.a);

    //float scale = max(iResolution.x, iResolution.y);
    float scale = 80.0; //brighter so we can visualise more easily

    if (texelFetch(iChannel1, ivec2(49, 2), 0).r >= 1.0) {
        vec4 cmyk = vec4(
            clamp(dist(last_top_right) / scale, 0.0, 1.0),
            clamp(dist(last_bottom_right) / scale, 0.0, 1.0),
            clamp(dist(last_bottom_left) / scale, 0.0, 1.0),
            clamp(dist(last_top_left) / scale, 0.0, 1.0)
        );

        fragColor = vec4(
            (1.0 - cmyk.xyz) * (1.0 - cmyk.w),
            1.0
        );
        return;
    }

    // get the min distance from the quadrant directional closest points
    float closest_dist = min(min(min(
        dist(last_top_right) / scale, 
        dist(last_bottom_right) / scale),
        dist(last_bottom_left) / scale),
        dist(last_top_left) / scale);

    fragColor = vec4(vec3(clamp(closest_dist, 0.0, 1.0)), 1.0);
}

// this buffer performs the initial scene sampling and closest point for direct neighbours in each axis

const float THRESHOLD = 0.61;

bool hit_scene(in ivec2 coord) {
    return texture(iChannel0, vec2(coord) / iResolution.xy).g < THRESHOLD;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    ivec2 coord = ivec2(floor(fragCoord));
    ivec2 res = ivec2(iResolution.xy);

    //sample this pixel first and just return if we get a result
    if (hit_scene(coord)) {
        fragColor = vec4(uintBitsToFloat(uint(0)));
        return;
    }

    // top
    uint closest_top = MAX_VALUE;
    uint max_top_offset = min(NUM_SAMPLES, uint(res.y - coord.y));
    for (uint offset=uint(1); offset<max_top_offset; offset++) {
        if (hit_scene(coord + ivec2(0, offset))) {
            closest_top = offset;
            break;
        }
    }

    // right
    uint closest_right = MAX_VALUE;
    uint max_right_offset = min(NUM_SAMPLES, uint(res.x - coord.x));
    for (uint offset=uint(1); offset<max_right_offset; offset++) {
        if (hit_scene(coord + ivec2(offset, 0))) {
            closest_right = offset;
            break;
        }
    }

    // bottom
    uint closest_bottom = MAX_VALUE;
    uint max_bottom_offset = min(NUM_SAMPLES, uint(coord.y));
    for (uint offset=uint(1); offset<max_bottom_offset; offset++) {
        if (hit_scene(coord + ivec2(0, -offset))) {
            closest_bottom = offset;
            break;
        }
    }

    // left
    uint closest_left = MAX_VALUE;
    uint max_left_offset = min(NUM_SAMPLES, uint(coord.x));
    for (uint offset=uint(1); offset<max_left_offset; offset++) {
        if (hit_scene(coord + ivec2(-offset, 0))) {
            closest_left = offset;
            break;
        }
    }

    fragColor = vec4(
        uintBitsToFloat(closest_top),
        uintBitsToFloat(closest_right),
        uintBitsToFloat(closest_bottom),
        uintBitsToFloat(closest_left)
    );
}

const uint NUM_SAMPLES = uint(64);

const uint MAX_VALUE = uint(8192);

// util functions

// some methods to package a 2 16-bit int into a single 32-bit float
float pack_2d_pos(in ivec2 pos) {
    return uintBitsToFloat(packSnorm2x16(vec2(pos) / 32767.0));
}

ivec2 unpack_2d_pos(in float col) {
    return ivec2(unpackSnorm2x16(floatBitsToUint(col)) * 32767.0);
}

float dist(in ivec2 a) {
    return length(vec2(a));
    //return sqrt(float((a.x * a.x) + (a.y * a.y)));
}

// this buffer completes computing closest point for each axis in the scene for each pixel

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    ivec2 coord = ivec2(floor(fragCoord));

    vec4 last_value = texelFetch(iChannel0, coord, 0);

    // top
    uint last_top = floatBitsToUint(last_value.r);

    if (last_top > NUM_SAMPLES) {
        uint max_offset = uint(iResolution.y) - uint(coord.y);

        for (uint offset=NUM_SAMPLES; offset<max_offset; offset+=NUM_SAMPLES) {
            vec4 top_neighbour = texelFetch(iChannel0, coord + ivec2(0, offset), 0);
            uint closest_top = floatBitsToUint(top_neighbour.r) + offset;

            if (closest_top < last_top) {
                last_top = closest_top;
                break;
            }
        }
    }

    // right
    uint last_right = floatBitsToUint(last_value.g);

    if (last_right > NUM_SAMPLES) {
        uint max_offset = uint(iResolution.x) - uint(coord.x);

        for (uint offset=NUM_SAMPLES; offset<max_offset; offset+=NUM_SAMPLES) {
            vec4 right_neighbour = texelFetch(iChannel0, coord + ivec2(offset, 0), 0);
            uint closest_right = floatBitsToUint(right_neighbour.g) + offset;

            if (closest_right < last_right) {
                last_right = closest_right;
                break;
            }
        }
    }

    // bottom
    uint last_bottom = floatBitsToUint(last_value.b);

    if (last_bottom > NUM_SAMPLES) {
        uint max_offset = uint(coord.y);

        for (uint offset=NUM_SAMPLES; offset<max_offset; offset+=NUM_SAMPLES) {
            vec4 bottom_neighbour = texelFetch(iChannel0, coord + ivec2(0, -offset), 0);
            uint closest_bottom = floatBitsToUint(bottom_neighbour.b) + offset;

            if (closest_bottom < last_bottom) {
                last_bottom = closest_bottom;
                break;
            }
        }
    }

    // left
    uint last_left = floatBitsToUint(last_value.a);

    if (last_left > NUM_SAMPLES) {
        uint max_offset = uint(coord.x);

        for (uint offset=NUM_SAMPLES; offset<max_offset; offset+=NUM_SAMPLES) {
            vec4 left_neighbour = texelFetch(iChannel0, coord + ivec2(-offset, 0), 0);
            uint closest_left = floatBitsToUint(left_neighbour.a) + offset;

            if (closest_left < last_left) {
                last_left = closest_left;
                break;
            }
        }
    }

    // store the accumulated closest point
    fragColor = vec4(
        uintBitsToFloat(last_top),
        uintBitsToFloat(last_right),
        uintBitsToFloat(last_bottom),
        uintBitsToFloat(last_left)
    );
}

// this buffer computes the closest point for neighbouring diagonals

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    ivec2 coord = ivec2(floor(fragCoord));
    ivec2 res = ivec2(iResolution.xy);

    vec4 distances = texelFetch(iChannel0, coord, 0);
    uint top_dist = floatBitsToUint(distances.r);
    uint right_dist = floatBitsToUint(distances.g);
    uint bottom_dist = floatBitsToUint(distances.b);
    uint left_dist = floatBitsToUint(distances.a);

    // top right
    ivec2 closest_top_right;
    float closest_top_right_dist;
    if (top_dist < right_dist) {
        closest_top_right = ivec2(0, int(top_dist));
        closest_top_right_dist = float(top_dist);
    } else {
        closest_top_right = ivec2(int(right_dist), 0);
        closest_top_right_dist = float(right_dist);
    }

    int max_top_right_offset = min(res.y - coord.y, min(res.x - coord.x, int(NUM_SAMPLES)));
    for (int offset=1; offset<max_top_right_offset; offset++) {
        ivec2 cell_offset = ivec2(offset, offset);

        vec4 next_cells = texelFetch(iChannel0, coord + cell_offset, 0);

        ivec2 closest_top = ivec2(0, int(floatBitsToUint(next_cells.r))) + cell_offset;
        float closest_top_distance = dist(closest_top);

        if (closest_top_distance < closest_top_right_dist) {
            closest_top_right = closest_top;
            closest_top_right_dist = closest_top_distance;
        }

        ivec2 closest_right = ivec2(int(floatBitsToUint(next_cells.g)), 0) + cell_offset;
        float closest_right_distance = dist(closest_right);

        if (closest_right_distance < closest_top_right_dist) {
            closest_top_right = closest_right;
            closest_top_right_dist = closest_right_distance;
        }
    }

    // bottom right
    ivec2 closest_bottom_right;
    float closest_bottom_right_dist;
    if (bottom_dist < right_dist) {
        closest_bottom_right = ivec2(0, -int(bottom_dist));
        closest_bottom_right_dist = float(bottom_dist);
    } else {
        closest_bottom_right = ivec2(int(right_dist), 0);
        closest_bottom_right_dist = float(right_dist);
    }

    int max_bottom_right_offset = min(coord.y, min(res.x - coord.x, int(NUM_SAMPLES)));
    for (int offset=1; offset<max_bottom_right_offset; offset++) {
        ivec2 cell_offset = ivec2(offset, -offset);

        vec4 next_cells = texelFetch(iChannel0, coord + cell_offset, 0);

        ivec2 closest_bottom = ivec2(0, -int(floatBitsToUint(next_cells.b))) + cell_offset;
        float closest_bottom_distance = dist(closest_bottom);

        if (closest_bottom_distance < closest_bottom_right_dist) {
            closest_bottom_right = closest_bottom;
            closest_bottom_right_dist = closest_bottom_distance;
        }

        ivec2 closest_right = ivec2(int(floatBitsToUint(next_cells.g)), 0) + cell_offset;
        float closest_right_distance = dist(closest_right);

        if (closest_right_distance < closest_bottom_right_dist) {
            closest_bottom_right = closest_right;
            closest_bottom_right_dist = closest_right_distance;
        }
    }

    // bottom left
    ivec2 closest_bottom_left;
    float closest_bottom_left_dist;
    if (bottom_dist < left_dist) {
        closest_bottom_left = ivec2(0, -int(bottom_dist));
        closest_bottom_left_dist = float(bottom_dist);
    } else {
        closest_bottom_left = ivec2(-int(left_dist), 0);
        closest_bottom_left_dist = float(left_dist);
    }

    int max_bottom_left_offset = min(coord.y, min(coord.x, int(NUM_SAMPLES)));
    for (int offset=1; offset<max_bottom_left_offset; offset++) {
        ivec2 cell_offset = ivec2(-offset);
        vec4 next_cells = texelFetch(iChannel0, coord + cell_offset, 0);

        ivec2 closest_bottom = ivec2(0, -int(floatBitsToUint(next_cells.b))) + cell_offset;
        float closest_bottom_distance = dist(closest_bottom);

        if (closest_bottom_distance < closest_bottom_left_dist) {
            closest_bottom_left = closest_bottom;
            closest_bottom_left_dist = closest_bottom_distance;
        }

        ivec2 closest_left = ivec2(-int(floatBitsToUint(next_cells.a)), 0) + cell_offset;
        float closest_left_distance = dist(closest_left);

        if (closest_left_distance < closest_bottom_left_dist) {
            closest_bottom_left = closest_left;
            closest_bottom_left_dist = closest_left_distance;
        }
    }

    // top left
    ivec2 closest_top_left;
    float closest_top_left_dist;
    if (top_dist < left_dist) {
        closest_top_left = ivec2(0, int(top_dist));
        closest_top_left_dist = float(top_dist);
    } else {
        closest_top_left = ivec2(-int(left_dist), 0);
        closest_top_left_dist = float(left_dist);
    }

    int max_top_left_offset = min(res.y - coord.y, min(coord.x, int(NUM_SAMPLES)));
    for (int offset=1; offset<max_top_left_offset; offset++) {
        ivec2 cell_offset = ivec2(-offset, offset);
        vec4 next_cells = texelFetch(iChannel0, coord + cell_offset, 0);

        ivec2 closest_top = ivec2(0, int(floatBitsToUint(next_cells.r))) + cell_offset;
        float closest_top_distance = dist(closest_top);

        if (closest_top_distance < closest_top_left_dist) {
            closest_top_left = closest_top;
            closest_top_left_dist = closest_top_distance;
        }

        ivec2 closest_left = ivec2(-int(floatBitsToUint(next_cells.a)), 0) + cell_offset;
        float closest_left_distance = dist(closest_left);

        if (closest_left_distance < closest_top_left_dist) {
            closest_top_left = closest_left;
            closest_top_left_dist = closest_left_distance;
        }
    }

    fragColor = vec4(
        pack_2d_pos(closest_top_right),
        pack_2d_pos(closest_bottom_right),
        pack_2d_pos(closest_bottom_left),
        pack_2d_pos(closest_top_left)
    );
}

// this buffer computes the closest point for neighbouring diagonals for the rest of the scene

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    ivec2 coord = ivec2(floor(fragCoord));
    ivec2 res = ivec2(iResolution.xy);

    // for later frames we lookup the diagonal closest points and compare them to the existing closest point
    int step_amount = int(NUM_SAMPLES);

    vec4 last_closest = texelFetch(iChannel0, coord, 0);

    // top right
    ivec2 last_top_right = unpack_2d_pos(last_closest.r);
    float top_right_dist = dist(last_top_right);
    int max_top_right_offset = min(res.y - coord.y, res.x - coord.x);

    for (int offset_amount = step_amount; offset_amount < max_top_right_offset; offset_amount += step_amount) {
        ivec2 offset = step_amount * ivec2(1);
        ivec2 test_top_right = unpack_2d_pos(texelFetch(iChannel0, coord + offset, 0).r) + offset;
        float test_top_right_dist = dist(test_top_right);

        if (test_top_right_dist < top_right_dist) {
            last_top_right = test_top_right;
            top_right_dist = test_top_right_dist;
        }
    }

    // bottom right
    ivec2 last_bottom_right = unpack_2d_pos(last_closest.g);
    float bottom_right_dist = dist(last_bottom_right);
    int max_bottom_right_offset = min(coord.y, res.x - coord.x);

    for (int offset_amount = step_amount; offset_amount < max_bottom_right_offset; offset_amount += step_amount) {
        ivec2 offset = step_amount * ivec2(1, -1);
        ivec2 test_bottom_right = unpack_2d_pos(texelFetch(iChannel0, coord + offset, 0).g) + offset;
        float test_bottom_right_dist = dist(test_bottom_right);

        if (test_bottom_right_dist < bottom_right_dist) {
            last_bottom_right = test_bottom_right;
            bottom_right_dist = test_bottom_right_dist;
        }
    }

    // bottom left
    ivec2 last_bottom_left = unpack_2d_pos(last_closest.b);
    float bottom_left_dist = dist(last_bottom_left);
    int max_bottom_left_offset = min(coord.y, coord.x);

    for (int offset_amount = step_amount; offset_amount < max_bottom_left_offset; offset_amount += step_amount) {
        ivec2 offset = step_amount * ivec2(-1);
        ivec2 test_bottom_left = unpack_2d_pos(texelFetch(iChannel0, coord + offset, 0).b) + offset;
        float test_bottom_left_dist = dist(test_bottom_left);

        if (test_bottom_left_dist < bottom_left_dist) {
            last_bottom_left = test_bottom_left;
            bottom_left_dist = test_bottom_left_dist;
        }
    }

    // top left
    ivec2 last_top_left = unpack_2d_pos(last_closest.a);
    float top_left_dist = dist(last_top_left);
    int max_top_left_offset = min(res.y - coord.y, coord.x);

    for (int offset_amount = step_amount; offset_amount < max_top_left_offset; offset_amount += step_amount) {
        ivec2 offset = step_amount * ivec2(-1, 1);
        ivec2 test_top_left = unpack_2d_pos(texelFetch(iChannel0, coord + offset, 0).a) + offset;
        float test_top_left_dist = dist(test_top_left);

        if (test_top_left_dist < top_left_dist) {
            last_top_left = test_top_left;
            top_left_dist = test_top_left_dist;
        }
    }

    // store the accumulated closest point
    fragColor = vec4(
        pack_2d_pos(last_top_right),
        pack_2d_pos(last_bottom_right),
        pack_2d_pos(last_bottom_left),
        pack_2d_pos(last_top_left)
    );
}
